"doom-fps/public/index.html" "<!DOCTYPE html>
<html lang=\"en\">
<head>
    <meta charset=\"UTF-8\">
    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">
    <title>Doom FPS</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #333; color: #eee; font-family: monospace; display: flex; justify-content: center; align-items: center; height: 100vh; }
    </style>
</head>
<body>
    <h1>Doom FPS Server Running!</h1>
    <script src=\"/socket.io/socket.io.js\"></script>
    <script>
        const socket = io();
        socket.on('connect', () => {
            console.log('Connected to server:', socket.id);
        });
        socket.on('disconnect', () => {
            console.log('Disconnected from server');
        });
    </script>
</body>
</html>" file-write
"doom-fps/server.js" "const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

const PORT = process.env.PORT || 3000;

// Serve static files from the 'public' directory
app.use(express.static('public'));

io.on('connection', (socket) => {
    console.log('A user connected:', socket.id);

    socket.on('disconnect', () => {
        console.log('User disconnected:', socket.id);
    });
});

server.listen(PORT, () => {
    console.log(\`Server listening on port \${PORT}\`);
    console.log('Visit http://localhost:3000');
});" file-write
